-- Чудо Обувь: 3НФ, PostgreSQL. Структура, GENERATED BY SQLAlchemy.

-- Данные импортируются отдельно из Приложения 2; скрипт ниже - только DDL.

BEGIN;


CREATE TABLE products (
	product_id SERIAL NOT NULL, 
	category VARCHAR(100) NOT NULL, 
	subcategory VARCHAR(100) NOT NULL, 
	product_name VARCHAR(200) NOT NULL, 
	manufacturer VARCHAR(200) NOT NULL, 
	image_path VARCHAR(500) NOT NULL, 
	description TEXT NOT NULL, 
	composition VARCHAR(500) NOT NULL, 
	price NUMERIC(12, 2) NOT NULL, 
	PRIMARY KEY (product_id), 
	CONSTRAINT ck_products_price CHECK (price >= 0)
)

;


CREATE TABLE roles (
	role_id SERIAL NOT NULL, 
	role_name VARCHAR(40) NOT NULL, 
	PRIMARY KEY (role_id), 
	UNIQUE (role_name)
)

;


CREATE TABLE sizes (
	size_id SERIAL NOT NULL, 
	size_value VARCHAR(24) NOT NULL, 
	PRIMARY KEY (size_id), 
	UNIQUE (size_value)
)

;


CREATE TABLE stock_items (
	stock_item_id SERIAL NOT NULL, 
	product_id INTEGER NOT NULL, 
	size_id INTEGER NOT NULL, 
	quantity_available INTEGER NOT NULL, 
	PRIMARY KEY (stock_item_id), 
	CONSTRAINT uq_stock_product_size UNIQUE (product_id, size_id), 
	CONSTRAINT ck_stock_quantity CHECK (quantity_available >= 0), 
	FOREIGN KEY(product_id) REFERENCES products (product_id) ON DELETE RESTRICT, 
	FOREIGN KEY(size_id) REFERENCES sizes (size_id) ON DELETE RESTRICT
)

;


CREATE TABLE users (
	user_id SERIAL NOT NULL, 
	last_name VARCHAR(100) NOT NULL, 
	first_name VARCHAR(100) NOT NULL, 
	middle_name VARCHAR(100) NOT NULL, 
	login VARCHAR(100) NOT NULL, 
	role_id INTEGER NOT NULL, 
	PRIMARY KEY (user_id), 
	UNIQUE (login), 
	FOREIGN KEY(role_id) REFERENCES roles (role_id) ON DELETE RESTRICT
)

;


CREATE TABLE orders (
	order_id SERIAL NOT NULL, 
	order_date DATE NOT NULL, 
	user_id INTEGER NOT NULL, 
	PRIMARY KEY (order_id), 
	FOREIGN KEY(user_id) REFERENCES users (user_id) ON DELETE RESTRICT
)

;


CREATE TABLE order_items (
	order_item_id SERIAL NOT NULL, 
	order_id INTEGER NOT NULL, 
	product_id INTEGER NOT NULL, 
	size_id INTEGER NOT NULL, 
	quantity INTEGER NOT NULL, 
	price NUMERIC(12, 2) NOT NULL, 
	PRIMARY KEY (order_item_id), 
	CONSTRAINT fk_order_item_stock_pair FOREIGN KEY(product_id, size_id) REFERENCES stock_items (product_id, size_id) ON DELETE RESTRICT, 
	CONSTRAINT ck_order_item_quantity CHECK (quantity > 0), 
	CONSTRAINT ck_order_item_price CHECK (price >= 0), 
	FOREIGN KEY(order_id) REFERENCES orders (order_id) ON DELETE CASCADE
)

;

COMMIT;
